68	    FutexWordType state = spin(spin_count);
69	    // Before go into contention state, try to grab the lock.
70	    if (state == UNLOCKED &&
71	        futex.compare_exchange_strong(state, LOCKED, cpp::MemoryOrder::ACQUIRE,
