1	//===--- Futex Wrapper ------------------------------------------*- C++ -*-===//
2	//
3	// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
4	// See https://llvm.org/LICENSE.txt for license information.
5	// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
6	//
7	//===----------------------------------------------------------------------===//
8	
9	#ifndef LLVM_LIBC_SRC___SUPPORT_THREADS_LINUX_FUTEX_UTILS_H
10	#define LLVM_LIBC_SRC___SUPPORT_THREADS_LINUX_FUTEX_UTILS_H
11	
12	#include "src/__support/CPP/atomic.h"
13	#include "src/__support/CPP/limits.h"
14	#include "src/__support/CPP/optional.h"
15	#include "src/__support/OSUtil/syscall.h"
16	#include "src/__support/error_or.h"
17	#include "src/__support/macros/attributes.h"
18	#include "src/__support/macros/config.h"
19	#include "src/__support/threads/linux/futex_word.h"
20	#include "src/__support/time/abs_timeout.h"
21	#include <linux/errno.h>
22	#include <linux/futex.h>
23	#if defined(SYS_futex_time64)
24	#include <linux/time_types.h>
25	#endif
26	
27	namespace LIBC_NAMESPACE_DECL {
28	
29	#if !defined(SYS_futex_time64) && defined(SYS_futex)
30	static_assert(
31	    sizeof(timespec::tv_nsec) == sizeof(long),
32	    "This legacy syscall fallback is only safe on platforms where tv_nsec "
33	    "matches the register size (long). It is unsafe on 32-bit platforms "
34	    "with 64-bit tv_nsec.");
35	#endif
36	
37	class Futex : public cpp::Atomic<FutexWordType> {
38	public:
39	  using Timeout = internal::AbsTimeout;
40	  LIBC_INLINE constexpr Futex(FutexWordType value)
41	      : cpp::Atomic<FutexWordType>(value) {}
42	  LIBC_INLINE Futex &operator=(FutexWordType value) {
43	    cpp::Atomic<FutexWordType>::store(value);
44	    return *this;
45	  }
46	  LIBC_INLINE ErrorOr<int> wait(FutexWordType expected,
47	                                cpp::optional<Timeout> timeout = cpp::nullopt,
48	                                bool is_shared = false) {
49	    // use bitset variants to enforce abs_time
50	    uint32_t op = is_shared ? FUTEX_WAIT_BITSET : FUTEX_WAIT_BITSET_PRIVATE;
51	    if (timeout && timeout->is_realtime()) {
52	      op |= FUTEX_CLOCK_REALTIME;
53	    }
54	    for (;;) {
55	      if (this->load(cpp::MemoryOrder::RELAXED) != expected)
56	        return 0;
57	
58	      void *timeout_ptr = nullptr;
59	#if defined(SYS_futex_time64)
60	      __kernel_timespec ts64;
61	      if (timeout) {
62	        // If timespec has the same size and layout as __kernel_timespec, we can
63	        // pass a pointer to it directly.
64	        if constexpr (sizeof(timespec) == sizeof(__kernel_timespec)) {
65	          timeout_ptr = const_cast<timespec *>(&timeout->get_timespec());
66	        } else {
67	          // Otherwise (e.g. 32-bit platforms with 32-bit time_t), the 64-bit
68	          // futex syscall (SYS_futex_time64) still expects a 64-bit timespec.
69	          // We must convert it to avoid passing a mismatching structure size.
70	          ts64.tv_sec = timeout->get_timespec().tv_sec;
71	          ts64.tv_nsec = timeout->get_timespec().tv_nsec;
72	          timeout_ptr = &ts64;
73	        }
74	      }
75	#else
76	      timespec ts;
77	      if (timeout) {
78	        ts = timeout->get_timespec();
79	        timeout_ptr = &ts;
80	      }
81	#endif
82	
83	      int ret = syscall_impl<int>(
84	          /*syscall_number=*/FUTEX_SYSCALL_ID,
85	          /*futex_addr=*/this,
86	          /*op=*/op,
87	          /*expected=*/expected,
88	          /*timeout=*/timeout_ptr,
89	          /*ignored=*/nullptr,
90	          /*bitset=*/FUTEX_BITSET_MATCH_ANY);
91	
92	      // continue waiting if interrupted; otherwise return the result
93	      // which should normally be 0 or -ETIMEOUT.
94	      if (ret == -EINTR)
95	        continue;
96	
97	      // EAGAIN and EWOULDBLOCK will be treated as a normal finish, as the value
98	      // has changed.
99	      if (ret == -EAGAIN || ret == -EWOULDBLOCK)
100	        return 0;
101	
102	      if (ret < 0)
103	        return cpp::unexpected(-ret);
104	      return ret;
105	    }
106	  }
107	  LIBC_INLINE ErrorOr<int> notify_one(bool is_shared = false) {
108	    int ret = syscall_impl<int>(
109	        /*syscall_number=*/FUTEX_SYSCALL_ID,
110	        /*futex_addr=*/this,
111	        /*op=*/is_shared ? FUTEX_WAKE : FUTEX_WAKE_PRIVATE,
112	        /*wake_limit=*/1,
113	        /*ignored=*/nullptr,
114	        /*ignored=*/nullptr,
115	        /* ignored */ 0);
116	    if (ret < 0)
117	      return cpp::unexpected(-ret);
118	    return ret;
119	  }
120	  LIBC_INLINE ErrorOr<int> notify_all(bool is_shared = false) {
121	    int ret = syscall_impl<int>(
122	        /*syscall_number=*/FUTEX_SYSCALL_ID,
123	        /*futex_addr=*/this,
124	        /*op=*/is_shared ? FUTEX_WAKE : FUTEX_WAKE_PRIVATE,
125	        /*wake_limit=*/cpp::numeric_limits<int>::max(),
126	        /*ignored=*/nullptr,
127	        /*ignored=*/nullptr,
128	        /*ignored=*/0);
129	    if (ret < 0)
130	      return cpp::unexpected(-ret);
131	    return ret;
132	  }
133	  LIBC_INLINE ErrorOr<int> requeue_to(Futex &other,
134	                                      cpp::optional<FutexWordType> oldval,
135	                                      int wake_limit, int requeue_limit,
136	                                      bool is_shared = false) {
137	    int ret;
138	    if (oldval)
139	      ret = syscall_impl<int>(
140	          /*syscall_number=*/FUTEX_SYSCALL_ID,
141	          /*futex_addr=*/this,
142	          /*op=*/
143	          is_shared ? FUTEX_CMP_REQUEUE : FUTEX_CMP_REQUEUE_PRIVATE,
144	          /*wake_limit=*/wake_limit,
145	          /*requeue_limit=*/requeue_limit,
146	          /*requeue_addr=*/&other, *oldval);
147	    else
148	      ret = syscall_impl<int>(
149	          /*syscall_number=*/FUTEX_SYSCALL_ID,
150	          /*futex_addr=*/this,
151	          /*op=*/is_shared ? FUTEX_REQUEUE : FUTEX_REQUEUE_PRIVATE,
152	          /*wake_limit=*/wake_limit,
153	          /*requeue_limit=*/requeue_limit,
154	          /*requeue_addr=*/&other);
155	    if (ret < 0)
156	      return cpp::unexpected<int>(-ret);
157	    return static_cast<int>(ret);
158	  }
159	};
160	
161	static_assert(__is_standard_layout(Futex),
162	              "Futex must be a standard layout type.");
163	} // namespace LIBC_NAMESPACE_DECL
164	
165	#endif // LLVM_LIBC_SRC___SUPPORT_THREADS_LINUX_FUTEX_UTILS_H
