46	static constexpr size_t NAME_SIZE_MAX = 16; // Includes the null terminator
47	static constexpr uint32_t CLEAR_TID_VALUE = 0xABCD1234;
48	static constexpr unsigned CLONE_SYSCALL_FLAGS =
49	    CLONE_VM        // Share the memory space with the parent.
50	    | CLONE_FS      // Share the file system with the parent.
51	    | CLONE_FILES   // Share the files with the parent.
52	    | CLONE_SIGHAND // Share the signal handlers with the parent.
53	    | CLONE_THREAD  // Same thread group as the parent.
54	    | CLONE_SYSVSEM // Share a single list of System V semaphore adjustment
55	                    // values
56	    | CLONE_PARENT_SETTID  // Set child thread ID in |ptid| of the parent.
57	    | CLONE_CHILD_CLEARTID // Let the kernel clear the tid address
58	                           // wake the joining thread.
59	    | CLONE_SETTLS;        // Setup the thread pointer of the new thread.
60	
61	#ifdef LIBC_TARGET_ARCH_IS_AARCH64
62	#define CLONE_RESULT_REGISTER "x0"
63	#elif defined(LIBC_TARGET_ARCH_IS_ANY_RISCV)
64	#define CLONE_RESULT_REGISTER "t0"
65	#elif defined(LIBC_TARGET_ARCH_IS_X86_64)
66	#define CLONE_RESULT_REGISTER "rax"
67	#else
68	#error "CLONE_RESULT_REGISTER not defined for your target architecture"
69	#endif
