71	static constexpr ErrorOr<size_t> add_no_overflow(size_t lhs, size_t rhs) {
72	  if (lhs > SIZE_MAX - rhs)
73	    return Error{EINVAL};
74	  if (rhs > SIZE_MAX - lhs)
75	    return Error{EINVAL};
76	  return lhs + rhs;
77	}
78	
79	static constexpr ErrorOr<size_t> round_to_page(size_t v) {
80	  auto vp_or_err = add_no_overflow(v, EXEC_PAGESIZE - 1);
81	  if (!vp_or_err)
82	    return vp_or_err;
83	
84	  return vp_or_err.value() & -EXEC_PAGESIZE;
85	}
86	
87	LIBC_INLINE ErrorOr<void *> alloc_stack(size_t stacksize, size_t guardsize) {
88	
89	  // Guard needs to be mapped with PROT_NONE
90	  int prot = guardsize ? PROT_NONE : PROT_READ | PROT_WRITE;
91	  auto size_or_err = add_no_overflow(stacksize, guardsize);
92	  if (!size_or_err)
93	    return Error{int(size_or_err.error())};
94	  size_t size = size_or_err.value();
95	
96	  // TODO: Maybe add MAP_STACK? Currently unimplemented on linux but helps
97	  // future-proof.
98	  ErrorOr<void *> mmap_result =
99	      linux_syscalls::mmap(nullptr, size, prot,
100	                           MAP_ANONYMOUS | MAP_PRIVATE, // Process private.
101	                           -1, // Not backed by any file
102	                           0   // No offset
103	      );
104	  if (!mmap_result.has_value())
105	    return mmap_result;
106	
107	  char *stack = static_cast<char *>(mmap_result.value()) + guardsize;
108	
109	  if (guardsize) {
110	    // Give read/write permissions to actual stack.
111	    // TODO: We are assuming stack growsdown here.
112	    auto result =
113	        linux_syscalls::mprotect(stack, stacksize, PROT_READ | PROT_WRITE);
114	
115	    if (!result)
116	      return Error{result.error()};
117	  }
118	  return stack;
119	}
120	
121	// This must always be inlined as we may be freeing the calling threads stack in
122	// which case a normal return from the top the stack would cause an invalid
123	// memory read.
124	[[gnu::always_inline]] LIBC_INLINE void
125	free_stack(void *stack, size_t stacksize, size_t guardsize) {
126	  uintptr_t stackaddr = reinterpret_cast<uintptr_t>(stack);
127	  stackaddr -= guardsize;
128	  stack = reinterpret_cast<void *>(stackaddr);
129	  linux_syscalls::munmap(stack, stacksize + guardsize);
130	}
131	
132	struct Thread;
133	
134	// We align the start args to 16-byte boundary as we adjust the allocated
135	// stack memory with its size. We want the adjusted address to be at a
136	// 16-byte boundary to satisfy the x86_64 and aarch64 ABI requirements.
137	// If different architecture in future requires higher alignment, then we
138	// can add a platform specific alignment spec.
139	struct alignas(STACK_ALIGNMENT) StartArgs {
140	  ThreadAttributes *thread_attrib;
141	  ThreadRunner runner;
142	  void *arg;
143	};
144	
145	// This must always be inlined as we may be freeing the calling threads stack in
146	// which case a normal return from the top the stack would cause an invalid
147	// memory read.
148	[[gnu::always_inline]] LIBC_INLINE void
149	cleanup_thread_resources(ThreadAttributes *attrib) {
150	  // Cleanup the TLS before the stack as the TLS information is stored on
151	  // the stack.
152	  cleanup_tls(attrib->tls, attrib->tls_size);
153	  if (attrib->owned_stack)
154	    free_stack(attrib->stack, attrib->stacksize, attrib->guardsize);
155	}
156	
157	[[gnu::always_inline]] LIBC_INLINE uintptr_t get_start_args_addr() {
158	// NOTE: For __builtin_frame_address to work reliably across compilers,
159	// architectures and various optimization levels, the TU including this file
160	// should be compiled with -fno-omit-frame-pointer.
161	#ifdef LIBC_TARGET_ARCH_IS_X86_64
162	  return reinterpret_cast<uintptr_t>(__builtin_frame_address(0))
163	         // The x86_64 call instruction pushes resume address on to the stack.
164	         // Next, The x86_64 SysV ABI requires that the frame pointer be pushed
165	         // on to the stack. So, we have to step past two 64-bit values to get
166	         // to the start args.
167	         + sizeof(uintptr_t) * 2;
168	#elif defined(LIBC_TARGET_ARCH_IS_AARCH64)
169	  // The frame pointer after cloning the new thread in the Thread::run method
170	  // is set to the stack pointer where start args are stored. So, we fetch
171	  // from there.
172	  return reinterpret_cast<uintptr_t>(__builtin_frame_address(1));
173	#elif defined(LIBC_TARGET_ARCH_IS_ANY_RISCV)
174	  // The current frame pointer is the previous stack pointer where the start
175	  // args are stored.
176	  return reinterpret_cast<uintptr_t>(__builtin_frame_address(0));
177	#endif
178	}
179	
180	[[gnu::noinline]] void start_thread() {
181	  auto *start_args = reinterpret_cast<StartArgs *>(get_start_args_addr());
182	  auto *attrib = start_args->thread_attrib;
183	  self.attrib = attrib;
184	  self.attrib->atexit_callback_mgr = internal::get_thread_atexit_callback_mgr();
185	
186	  if (attrib->style == ThreadStyle::POSIX) {
187	    attrib->retval.posix_retval =
188	        start_args->runner.posix_runner(start_args->arg);
189	    thread_exit(ThreadReturnValue(attrib->retval.posix_retval),
190	                ThreadStyle::POSIX);
191	  } else {
192	    attrib->retval.stdc_retval =
193	        start_args->runner.stdc_runner(start_args->arg);
194	    thread_exit(ThreadReturnValue(attrib->retval.stdc_retval),
195	                ThreadStyle::STDC);
196	  }
197	}
198	
199	int Thread::run(ThreadStyle style, ThreadRunner runner, void *arg, void *stack,
200	                size_t stacksize, size_t guardsize, bool detached) {
201	  bool owned_stack = false;
202	  if (stack == nullptr) {
203	    // TODO: Should we return EINVAL here? Should we have a generic concept of a
204	    //       minimum stacksize (like 16384 for pthread).
205	    if (stacksize == 0)
206	      stacksize = DEFAULT_STACKSIZE;
207	    // Roundup stacksize/guardsize to page size.
208	    // TODO: Should be also add sizeof(ThreadAttribute) and other internal
209	    //       meta data?
210	    auto round_or_err = round_to_page(guardsize);
211	    if (!round_or_err)
212	      return round_or_err.error();
213	    guardsize = round_or_err.value();
214	
215	    round_or_err = round_to_page(stacksize);
216	    if (!round_or_err)
217	      return round_or_err.error();
218	
219	    stacksize = round_or_err.value();
220	    auto alloc = alloc_stack(stacksize, guardsize);
221	    if (!alloc)
222	      return alloc.error();
223	    else
224	      stack = alloc.value();
225	    owned_stack = true;
226	  }
227	
228	  // Validate that stack/stacksize are validly aligned.
229	  uintptr_t stackaddr = reinterpret_cast<uintptr_t>(stack);
230	  if ((stackaddr % STACK_ALIGNMENT != 0) ||
231	      ((stackaddr + stacksize) % STACK_ALIGNMENT != 0)) {
232	    if (owned_stack)
233	      free_stack(stack, stacksize, guardsize);
234	    return EINVAL;
235	  }
236	
237	  TLSDescriptor tls;
238	  init_tls(tls);
239	
240	  // When the new thread is spawned by the kernel, the new thread gets the
241	  // stack we pass to the clone syscall. However, this stack is empty and does
242	  // not have any local vars present in this function. Hence, one cannot
243	  // pass arguments to the thread start function, or use any local vars from
244	  // here. So, we pack them into the new stack from where the thread can sniff
245	  // them out.
246	  //
247	  // Likewise, the actual thread state information is also stored on the
248	  // stack memory.
249	
250	  static constexpr size_t INTERNAL_STACK_DATA_SIZE =
251	      sizeof(StartArgs) + sizeof(ThreadAttributes) + sizeof(Futex);
252	
253	  // This is pretty arbitrary, but at the moment we don't adjust user provided
254	  // stacksize (or default) to account for this data as its assumed minimal. If
255	  // this assert starts failing we probably should. Likewise if we can't bound
256	  // this we may overflow when we subtract it from the top of the stack.
257	  static_assert(INTERNAL_STACK_DATA_SIZE < EXEC_PAGESIZE);
258	
259	  // TODO: We are assuming stack growsdown here.
260	  auto adjusted_stack_or_err =
261	      add_no_overflow(reinterpret_cast<uintptr_t>(stack), stacksize);
262	  if (!adjusted_stack_or_err) {
263	    cleanup_tls(tls.addr, tls.size);
264	    if (owned_stack)
265	      free_stack(stack, stacksize, guardsize);
266	    return adjusted_stack_or_err.error();
267	  }
268	
269	  uintptr_t adjusted_stack =
270	      adjusted_stack_or_err.value() - INTERNAL_STACK_DATA_SIZE;
271	  adjusted_stack &= ~(uintptr_t(STACK_ALIGNMENT) - 1);
272	
273	  auto *start_args = reinterpret_cast<StartArgs *>(adjusted_stack);
274	
275	  attrib =
276	      reinterpret_cast<ThreadAttributes *>(adjusted_stack + sizeof(StartArgs));
277	  attrib->style = style;
278	  attrib->detach_state =
279	      uint32_t(detached ? DetachState::DETACHED : DetachState::JOINABLE);
280	  attrib->stack = stack;
281	  attrib->stacksize = stacksize;
282	  attrib->guardsize = guardsize;
283	  attrib->owned_stack = owned_stack;
284	  attrib->tls = tls.addr;
285	  attrib->tls_size = tls.size;
286	  attrib->joiner = nullptr;
287	
288	  start_args->thread_attrib = attrib;
289	  start_args->runner = runner;
290	  start_args->arg = arg;
291	
292	  auto clear_tid = reinterpret_cast<Futex *>(
293	      adjusted_stack + sizeof(StartArgs) + sizeof(ThreadAttributes));
294	  clear_tid->set(CLEAR_TID_VALUE);
295	  attrib->platform_data = clear_tid;
296	
297	  // The clone syscall takes arguments in an architecture specific order.
298	  // Also, we want the result of the syscall to be in a register as the child
299	  // thread gets a completely different stack after it is created. The stack
300	  // variables from this function will not be availalbe to the child thread.
301	#if defined(LIBC_TARGET_ARCH_IS_X86_64)
302	  long register clone_result asm(CLONE_RESULT_REGISTER);
303	  clone_result = LIBC_NAMESPACE::syscall_impl<long>(
304	      SYS_clone, CLONE_SYSCALL_FLAGS, adjusted_stack,
305	      &attrib->tid,    // The address where the child tid is written
306	      &clear_tid->val, // The futex where the child thread status is signalled
307	      tls.tp           // The thread pointer value for the new thread.
308	  );
309	#elif defined(LIBC_TARGET_ARCH_IS_AARCH64) ||                                  \
310	    defined(LIBC_TARGET_ARCH_IS_ANY_RISCV)
311	  long register clone_result asm(CLONE_RESULT_REGISTER);
312	  clone_result = LIBC_NAMESPACE::syscall_impl<long>(
313	      SYS_clone, CLONE_SYSCALL_FLAGS, adjusted_stack,
314	      &attrib->tid,   // The address where the child tid is written
315	      tls.tp,         // The thread pointer value for the new thread.
316	      &clear_tid->val // The futex where the child thread status is signalled
317	  );
318	#else
319	#error "Unsupported architecture for the clone syscall."
320	#endif
321	
322	  if (clone_result == 0) {
323	#ifdef LIBC_TARGET_ARCH_IS_AARCH64
324	    // We set the frame pointer to be the same as the "sp" so that start args
325	    // can be sniffed out from start_thread.
326	#ifdef __clang__
327	    // GCC does not currently implement __arm_wsr64/__arm_rsr64.
328	    __arm_wsr64("x29", __arm_rsr64("sp"));
329	#else
330	    asm volatile("mov x29, sp");
331	#endif
332	#elif defined(LIBC_TARGET_ARCH_IS_ANY_RISCV)
333	    asm volatile("mv fp, sp");
334	#endif
335	    start_thread();
336	  } else if (clone_result < 0) {
337	    cleanup_thread_resources(attrib);
338	    return static_cast<int>(-clone_result);
339	  }
340	
341	  return 0;
342	}
343	
344	int Thread::join(ThreadReturnValue &retval) {
345	  if (self.attrib) {
346	    // Reject self join.
347	    if (self.attrib == attrib)
348	      return EDEADLK;
349	
350	    // Do a best-effort check of concurrent/repeated join.
351	    // This cmpxchg establishes exclusive joiner role by setting the joiner
352	    // field iff there is no previous joiner
353	    ThreadAttributes *expected = nullptr;
354	    if (!attrib->joiner.compare_exchange_strong(expected, self.attrib,
355	                                                cpp::MemoryOrder::ACQ_REL))
356	      return EINVAL;
357	
358	    // Reject mutual join.
359	    if (self.attrib->joiner.load(cpp::MemoryOrder::ACQUIRE) == attrib) {
360	      attrib->joiner.store(nullptr, cpp::MemoryOrder::RELEASE);
361	      return EDEADLK;
362	    }
363	  }
364	
365	  wait();
366	
367	  if (attrib->style == ThreadStyle::POSIX)
368	    retval.posix_retval = attrib->retval.posix_retval;
369	  else
370	    retval.stdc_retval = attrib->retval.stdc_retval;
371	
372	  cleanup_thread_resources(attrib);
373	
374	  return 0;
375	}
376	
377	int Thread::detach() {
378	  uint32_t joinable_state = uint32_t(DetachState::JOINABLE);
379	  if (attrib->detach_state.compare_exchange_strong(
380	          joinable_state, uint32_t(DetachState::DETACHED))) {
381	    return int(DetachType::SIMPLE);
382	  }
383	
384	  // If the thread was already detached, then the detach method should not
385	  // be called at all. If the thread is exiting, then we wait for it to exit
386	  // and free up resources.
387	  wait();
388	
389	  cleanup_thread_resources(attrib);
390	
391	  return int(DetachType::CLEANUP);
392	}
393	
394	void Thread::wait() {
395	  // The kernel should set the value at the clear tid address to zero.
396	  // If not, it is a spurious wake and we should continue to wait on
397	  // the futex.
398	  auto *clear_tid = reinterpret_cast<Futex *>(attrib->platform_data);
399	  // We cannot do a FUTEX_WAIT_PRIVATE here as the kernel does a
400	  // FUTEX_WAKE and not a FUTEX_WAKE_PRIVATE.
401	  while (clear_tid->load() != 0)
402	    clear_tid->wait(CLEAR_TID_VALUE, cpp::nullopt, true);
403	}
404	
405	bool Thread::operator==(const Thread &thread) const {
406	  return attrib->tid == thread.attrib->tid;
407	}
