409	static constexpr cpp::string_view THREAD_NAME_PATH_PREFIX("/proc/self/task/");
410	static constexpr size_t THREAD_NAME_PATH_SIZE =
411	    THREAD_NAME_PATH_PREFIX.size() +
412	    IntegerToString<int>::buffer_size() + // Size of tid
413	    1 +                                   // For '/' character
414	    5; // For the file name "comm" and the nullterminator.
415	
416	static void construct_thread_name_file_path(cpp::StringStream &stream,
417	                                            int tid) {
418	  stream << THREAD_NAME_PATH_PREFIX << tid << '/' << cpp::string_view("comm")
419	         << cpp::StringStream::ENDS;
420	}
421	
422	int Thread::set_name(const cpp::string_view &name) {
423	  if (name.size() >= NAME_SIZE_MAX)
424	    return ERANGE;
425	
426	  if (*this == self) {
427	    // If we are setting the name of the current thread, then we can
428	    // use the syscall to set the name.
429	    int retval =
430	        LIBC_NAMESPACE::syscall_impl<int>(SYS_prctl, PR_SET_NAME, name.data());
431	    if (retval < 0)
432	      return -retval;
433	    else
434	      return 0;
435	  }
436	
437	  char path_name_buffer[THREAD_NAME_PATH_SIZE];
438	  cpp::StringStream path_stream(path_name_buffer);
439	  construct_thread_name_file_path(path_stream, attrib->tid);
440	  ErrorOr<int> fd = linux_syscalls::open(path_name_buffer, O_RDWR, 0);
441	  if (!fd)
442	    return fd.error();
443	
444	  auto write_result =
445	      linux_syscalls::write(fd.value(), name.data(), name.size());
446	  linux_syscalls::close(fd.value());
447	
448	  if (!write_result)
449	    return write_result.error();
450	  else if (write_result.value() != static_cast<ssize_t>(name.size()))
451	    return EIO;
452	  else
453	    return 0;
454	}
455	
456	int Thread::get_name(cpp::StringStream &name) const {
457	  if (name.bufsize() < NAME_SIZE_MAX)
458	    return ERANGE;
459	
460	  char name_buffer[NAME_SIZE_MAX];
461	
462	  if (*this == self) {
463	    // If we are getting the name of the current thread, then we can
464	    // use the syscall to get the name.
465	    int retval =
466	        LIBC_NAMESPACE::syscall_impl<int>(SYS_prctl, PR_GET_NAME, name_buffer);
467	    if (retval < 0)
468	      return -retval;
469	    name << name_buffer << cpp::StringStream::ENDS;
470	    return 0;
471	  }
472	
473	  char path_name_buffer[THREAD_NAME_PATH_SIZE];
474	  cpp::StringStream path_stream(path_name_buffer);
475	  construct_thread_name_file_path(path_stream, attrib->tid);
476	  ErrorOr<int> fd = linux_syscalls::open(path_name_buffer, O_RDONLY, 0);
477	  if (!fd)
478	    return fd.error();
479	
480	  auto read_result =
481	      linux_syscalls::read(fd.value(), name_buffer, NAME_SIZE_MAX);
482	  linux_syscalls::close(fd.value());
483	  if (!read_result)
484	    return read_result.error();
485	  int retval = static_cast<int>(read_result.value());
486	  if (retval == NAME_SIZE_MAX)
487	    return ERANGE;
488	  if (name_buffer[retval - 1] == '\n')
489	    name_buffer[retval - 1] = '\0';
490	  else
491	    name_buffer[retval] = '\0';
492	  name << name_buffer << cpp::StringStream::ENDS;
493	  return 0;
494	}
495	
496	int Thread::setschedparam(SchedParameters params) {
497	  auto result = linux_syscalls::sched_setscheduler(attrib->tid, params.policy,
498	                                                   &params.param);
499	  if (!result.has_value())
500	    return result.error();
501	  return 0;
502	}
503	
504	ErrorOr<SchedParameters> Thread::getschedparam() const {
505	  auto pol_result = linux_syscalls::sched_getscheduler(attrib->tid);
506	  if (!pol_result.has_value())
507	    return Error(pol_result.error());
508	
509	  struct sched_param param;
510	  auto param_result = linux_syscalls::sched_getparam(attrib->tid, &param);
511	  if (!param_result.has_value())
512	    return Error(param_result.error());
513	
514	  return SchedParameters{pol_result.value(), param};
515	}
516	
517	void thread_exit(ThreadReturnValue retval, ThreadStyle style) {
518	  auto attrib = self.attrib;
519	
520	  // The very first thing we do is to call the thread's atexit callbacks.
521	  // These callbacks could be the ones registered by the language runtimes,
522	  // for example, the destructors of thread local objects. They can also
523	  // be destructors of the TSS objects set using API like pthread_setspecific.
524	  // NOTE: We cannot call the atexit callbacks as part of the
525	  // cleanup_thread_resources function as that function can be called from a
526	  // different thread. The destructors of thread local and TSS objects should
527	  // be called by the thread which owns them.
528	  internal::call_atexit_callbacks(attrib);
529	
530	  uint32_t joinable_state = uint32_t(DetachState::JOINABLE);
531	  if (!attrib->detach_state.compare_exchange_strong(
532	          joinable_state, uint32_t(DetachState::EXITING))) {
533	    // Thread is detached so cleanup the resources.
534	    cleanup_thread_resources(attrib);
535	
536	    // Set the CLEAR_TID address to nullptr to prevent the kernel
537	    // from signalling at a non-existent futex location.
538	    LIBC_NAMESPACE::syscall_impl<long>(SYS_set_tid_address, 0);
539	    // Return value for detached thread should be unused. We need to avoid
540	    // referencing `style` or `retval.*` because they may be stored on the stack
541	    // and we have deallocated our stack!
542	    LIBC_NAMESPACE::syscall_impl<long>(SYS_exit, 0);
543	    __builtin_unreachable();
544	  }
545	
546	  if (style == ThreadStyle::POSIX)
547	    LIBC_NAMESPACE::syscall_impl<long>(SYS_exit, retval.posix_retval);
548	  else
549	    LIBC_NAMESPACE::syscall_impl<long>(SYS_exit, retval.stdc_retval);
550	  __builtin_unreachable();
551	}
552	
553	} // namespace LIBC_NAMESPACE_DECL
